/** Real native source, unscaled logical reference and authored sliding shaft contacts. */
public final class AirTridentAudit {
 private static final java.util.Map<net.minecraft.world.entity.player.PlayerModelType,net.minecraft.client.model.player.PlayerModel> MODELS=new java.util.EnumMap<>(net.minecraft.world.entity.player.PlayerModelType.class);
 public static boolean enabled,submittingExpectedItem;public static int frames,full,specialGpu;public static float maxMainGap,maxSupportGap,minContact,maxContact;
 public static net.minecraft.client.renderer.item.ItemStackRenderState expectedItem;public static Vector3f expectedGrip,expectedAxis,mainPalm,supportPalm;public static String clip;
 public static void begin(){enabled=true;frames=full=specialGpu=0;maxMainGap=maxSupportGap=0;minContact=99;maxContact=-99;expectedItem=null;submittingExpectedItem=false;clip=null;}
 public static void observe(AvatarRenderState state){
  var f=state.getData(CombatRigLayer.FRAME);if(!enabled||f==null||!f.clip().startsWith("trident_attack_air_"))return;frames++;clip=f.clip();if(!BackTransitions.held(state,state.mainArm).is(Items.TRIDENT))throw new AssertionError("Actual main native trident source only");if(f.weight()<.999999F)return;full++;
  var model=MODELS.computeIfAbsent(state.skin.model(),type->{boolean slim=type==net.minecraft.world.entity.player.PlayerModelType.SLIM;return new net.minecraft.client.model.player.PlayerModel(net.minecraft.client.model.geom.builders.LayerDefinition.create(net.minecraft.client.model.player.PlayerModel.createMesh(net.minecraft.client.model.geom.builders.CubeDeformation.NONE,slim),64,64).bakeRoot(),slim);});model.setupAnim(state);var pose=new com.mojang.blaze3d.vertex.PoseStack();model.head.translateAndRotate(pose);var aim=new Matrix4f(CombatRigLayer.BASIS).mul(pose.last().pose()).mul(CombatRigLayer.BASIS).getUnnormalizedRotation(new org.joml.Quaternionf()).normalize();if(Math.abs(aim.dot(f.global()[Arrays.asList(f.data().bones()).indexOf("head")].getUnnormalizedRotation(new org.joml.Quaternionf()).normalize()))<.99999F)throw new AssertionError("Ground source must preserve independent current native head aim");
  var names=Arrays.asList(f.data().bones());var source=CombatRig.sample(f.data().variant(),f.clip(),f.time());for(String side:new String[]{"left","right"})source[names.indexOf(side+"_palm_grip")].setTranslation(source[names.indexOf(side+"_wrist")].transformPosition(new Vector3f(0,.0625F,0)));if(BackTransitions.held(state,state.mainArm.getOpposite()).is(Items.SHIELD))source[names.indexOf((state.mainArm==HumanoidArm.RIGHT?"left":"right")+"_shield_mount")].translate(0,.125F,0);
  var other=state.mainArm.getOpposite();if(BackTransitions.held(state,other).is(Items.SHIELD)){var item=other==HumanoidArm.RIGHT?state.rightHandItemState:state.leftHandItemState;Matrix4f held;DodgeFeedbackAudit.checkingNativeItem=true;try{held=CombatRig.heldPose(f,item,other,true);}finally{DodgeFeedbackAudit.checkingNativeItem=false;}var layer=(dev.wildcraft.mixin.client.FusionLayerAccessor)((dev.wildcraft.mixin.client.FusionStateAccessor)item).wildcraft$layers()[0];var p=new com.mojang.blaze3d.vertex.PoseStack();layer.wildcraft$transform().apply(other==HumanoidArm.LEFT,p.last());p.mulPose(layer.wildcraft$local());var handle=held.transformPosition(p.last().pose().transformPosition(new Vector3f(0,0,.125F)));var palm=new Matrix4f(CombatRigLayer.BASIS).mul(f.global()[names.indexOf((other==HumanoidArm.RIGHT?"right":"left")+"_palm_grip")]).getTranslation(new Vector3f());if(handle.distance(palm)>.015F)throw new AssertionError("Actual carried native shield handle lost ground-source skin palm "+handle.distance(palm));}
  for(int i=0;i<source.length;i++){if(names.get(i).equals("head"))continue;float[] a=source[i].get(new float[16]),b=f.global()[i].get(new float[16]);for(int k=0;k<16;k++)if(Math.abs(a[k]-b[k])>2e-5F)throw new AssertionError("Ground trident source changed authored skin/sliding reference "+names.get(i));}
  String main=state.mainArm==HumanoidArm.RIGHT?"right":"left",off=state.mainArm==HumanoidArm.RIGHT?"left":"right";var ref=f.global()[names.indexOf(main+"_sword_reference")];var center=ref.getTranslation(new Vector3f());var axis=ref.transformDirection(new Vector3f(0,1,0)).normalize();
  var palm=f.global()[names.indexOf(main+"_palm_grip")].getTranslation(new Vector3f());float along=new Vector3f(palm).sub(center).dot(axis),contact=1.1F-along,gap=new Vector3f(center).fma(along,axis).distance(palm);if(gap>.015F||contact<.125F||contact>1.6875F)throw new AssertionError("Main physical palm left actual native pole "+gap+" y="+contact);maxMainGap=Math.max(maxMainGap,gap);minContact=Math.min(minContact,contact);maxContact=Math.max(maxContact,contact);
  if(BackTransitions.held(state,state.mainArm.getOpposite()).isEmpty()){palm=f.global()[names.indexOf(off+"_palm_grip")].getTranslation(new Vector3f());along=new Vector3f(palm).sub(center).dot(axis);gap=new Vector3f(center).fma(along,axis).distance(palm);if(gap>.015F)throw new AssertionError("Free support palm left source pole "+gap);maxSupportGap=Math.max(maxSupportGap,gap);}
 }
 public static void handRoot(AvatarRenderState state,net.minecraft.client.renderer.item.ItemStackRenderState item,HumanoidArm arm,com.mojang.blaze3d.vertex.PoseStack parent){expectedItem=null;var f=state.getData(CombatRigLayer.FRAME);if(!enabled||f==null||!f.clip().startsWith("trident_attack_air_")||f.weight()<.999999F||arm!=state.mainArm)return;var names=Arrays.asList(f.data().bones());String main=arm==HumanoidArm.RIGHT?"right":"left",off=arm==HumanoidArm.RIGHT?"left":"right";var basis=new Matrix4f(parent.last().pose()).mul(CombatRigLayer.BASIS);var ref=new Matrix4f(basis).mul(f.global()[names.indexOf(main+"_sword_reference")]);expectedGrip=ref.getTranslation(new Vector3f());expectedAxis=ref.transformDirection(new Vector3f(0,1,0)).normalize();mainPalm=basis.transformPosition(f.global()[names.indexOf(main+"_palm_grip")].getTranslation(new Vector3f()));supportPalm=BackTransitions.held(state,arm.getOpposite()).isEmpty()?basis.transformPosition(f.global()[names.indexOf(off+"_palm_grip")].getTranslation(new Vector3f())):null;expectedItem=item;}
 public static void nativeModel(com.mojang.blaze3d.vertex.PoseStack poses){if(!enabled||!submittingExpectedItem)return;var model=poses.last().pose();var grip=model.transformPosition(new Vector3f(0,1.1F,0));var tip=model.transformPosition(new Vector3f(0,0,0));var axis=new Vector3f(tip).sub(grip).normalize();if(grip.distance(expectedGrip)>2e-5F||axis.dot(expectedAxis)<.99999F)throw new AssertionError("Actual native TridentSpecialRenderer lost logical sliding reference/axis");var lo=model.transformPosition(new Vector3f(0,.125F,0));var hi=model.transformPosition(new Vector3f(0,1.6875F,0));var shaft=new Vector3f(hi).sub(lo);for(var palm:supportPalm==null?new Vector3f[]{mainPalm}:new Vector3f[]{mainPalm,supportPalm}){float t=new Vector3f(palm).sub(lo).dot(shaft)/shaft.lengthSquared();float gap=new Vector3f(lo).fma(Math.clamp(t,0,1),shaft).distance(palm);if(t<0||t>1||gap>.015F)throw new AssertionError("Actual rendered native pole does not meet physical skin palm "+gap+" t="+t);}specialGpu++;}
}
